<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api.js'
import ExaminerSlotsTable from '../components/ExaminerSlotsTable.vue'
import WorkSubmissionModal from '../components/WorkSubmissionModal.vue'
import { auth, notify } from '../state.js'
import '../admin.css'
const props=defineProps({title:String,section:String})
const router=useRouter(),loading=ref(false),error=ref(''),items=ref([]),detail=ref(null),search=ref(''),status=ref(''),page=ref(1),pages=ref(1),total=ref(0),examinations=ref([]),selectedExam=ref(''),slotForm=ref({starts_at:'',ends_at:'',capacity:1,meeting_link:''}),slotTimeStep=ref(15),scoreRows=ref([]),evaluation=ref(null),profile=ref({}),saving=ref(false),result=ref(null),courseFilter=ref(''),typeFilter=ref('')
const examiner=auth.user?.role==='examiner'
const submissionBooking=ref(null)
const endpoints={
 'my-examinations':'/examiner/examinations','my-slots':'/examiner/slots','booked-students':'/examiner/booked-students','evaluations':'/examiner/evaluations',
 'browse-examinations':'/student/examinations','my-bookings':'/student/bookings','examination-history':'/student/bookings?status=completed','results':'/student/results'}
const listEndpoint=computed(()=>endpoints[props.section])
async function load(){loading.value=true;error.value='';try{
 if(props.section==='profile'){profile.value=await api.request(examiner?'/examiner/profile':'/student/profile');return}
 if(props.section==='my-slots'){const q=new URLSearchParams({page:String(page.value),per_page:'20'});if(search.value)q.set('examination_id',search.value);const r=await api.request(`/examiner/slots?${q}`);items.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total;examinations.value=(await api.request('/examiner/examinations?per_page=100')).items;return}
 if(props.section==='evaluations'||props.section==='booked-students'){const q=new URLSearchParams({page:String(page.value),per_page:'20'});if(status.value)q.set('status',status.value);if(props.section==='evaluations'){const r=await api.request(`/examiner/evaluations?${q}`);items.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total}else{const r=await api.request(`/examiner/booked-students?${q}`);items.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total}return}
 if(props.section==='my-bookings'||props.section==='examination-history'){const q=new URLSearchParams({page:String(page.value),per_page:'20'});if(search.value)q.set('search',search.value);if(props.section==='my-bookings'&&status.value)q.set('status',status.value);const r=await api.request(`/student/bookings?${q}`);items.value=r.items.filter(x=>props.section==='examination-history'?x.status!=='booked':true);pages.value=r.pagination.pages;total.value=r.pagination.total;return}
 if(props.section==='browse-examinations'){const q=new URLSearchParams({page:String(page.value),per_page:'20'});if(search.value)q.set('search',search.value);if(courseFilter.value)q.set('course_id',courseFilter.value);if(typeFilter.value)q.set('type',typeFilter.value);const r=await api.request(`/student/examinations?${q}`);items.value=r.items;examinations.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total;return}
 if(props.section==='results'){const r=await api.request(`/student/results?page=${page.value}&per_page=20`);items.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total;return}
 if(props.section==='my-examinations'){const q=new URLSearchParams({page:String(page.value),per_page:'20'});if(search.value)q.set('search',search.value);const r=await api.request(`/examiner/examinations?${q}`);items.value=r.items;pages.value=r.pagination.pages;total.value=r.pagination.total;return}
}catch(e){error.value=e.message}finally{loading.value=false}}
watch(()=>props.section,load);watch([search,status,page],load);onMounted(load)
async function inspect(x){try{const path=examiner?`/examiner/examinations/${x.id}`:`/student/examinations/${x.id}`;detail.value=await api.request(path)}catch(e){notify(e.message,'danger')}}
async function book(slot){if(!confirm(`Book this ${fmt(slot.starts_at)} examination slot?`))return;try{const r=await api.request('/student/bookings',{method:'POST',body:JSON.stringify({slot_id:slot.id})});notify(`Booking confirmed · reference ${r.item.id}`);detail.value=null;await load()}catch(e){notify(e.message,'danger')}}
async function cancel(x){if(!confirm(`Cancel booking ${x.id} for ${x.examination}?`))return;try{await api.request(`/student/bookings/${x.id}/cancel`,{method:'POST'});notify('Booking cancelled; the seat is available again.');await load()}catch(e){notify(e.message,'danger')}}
async function createSlot(){saving.value=true;try{await api.request('/examiner/slots',{method:'POST',body:JSON.stringify({...slotForm.value,examination_id:Number(selectedExam.value),starts_at:new Date(slotForm.value.starts_at).toISOString(),ends_at:new Date(slotForm.value.ends_at).toISOString(),capacity:Number(slotForm.value.capacity)})});notify('Slot created');slotForm.value={starts_at:'',ends_at:'',capacity:1,meeting_link:''};await load()}catch(e){notify(e.message,'danger')}finally{saving.value=false}}
async function slotAction(x,action){try{if(action==='cancel'&&!confirm('Cancel this slot? Slots with active bookings cannot be cancelled.'))return;let body;if(action==='capacity'){const value=prompt('New capacity:',x.capacity);if(value===null)return;body=JSON.stringify({capacity:Number(value)})}await api.request(`/examiner/slots/${x.id}`,{method:action==='cancel'?'DELETE':'PATCH',...(body?{body}:{})});notify(action==='cancel'?'Slot cancelled':'Slot updated');await load()}catch(e){notify(e.message,'danger')}}
async function openEvaluation(x){try{const r=await api.request(`/examiner/bookings/${x.booking_id}/evaluation`);detail.value=r.booking;evaluation.value=r.evaluation;scoreRows.value=r.rubric.map(c=>({...c,score:r.evaluation?.criteria?.find(s=>s.criterion_id===c.id)?.score??'',feedback:r.evaluation?.criteria?.find(s=>s.criterion_id===c.id)?.feedback??''}))}catch(e){notify(e.message,'danger')}}
async function downloadWork(submission){try{await api.download(submission.download_url,submission.filename)}catch(e){notify(e.message,'danger')}}
async function saveEvaluation(submit){saving.value=true;try{const r=await api.request(`/examiner/bookings/${detail.value.id}/evaluation`,{method:'PUT',body:JSON.stringify({submit,criteria:scoreRows.value.map(c=>({criterion_id:c.id,score:c.score===''?null:Number(c.score),feedback:c.feedback||''}))})});evaluation.value=r.item;notify(submit?'Evaluation submitted and locked':'Draft saved');if(submit){detail.value=null;await load()}}catch(e){notify(e.message,'danger')}finally{saving.value=false}}
async function showResult(x){try{result.value=(await api.request(`/student/results/${x.evaluation_id}`)).item}catch(e){notify(e.message,'danger')}}
async function saveProfile(){saving.value=true;try{const path=examiner?'/examiner/profile':'/student/profile';await api.request(path,{method:'PATCH',body:JSON.stringify(examiner?{full_name:profile.value.user.full_name,email:profile.value.user.email,department:profile.value.department}:{full_name:profile.value.user.full_name,email:profile.value.user.email,program:profile.value.program,department:profile.value.department,student_number:profile.value.student_number})});notify('Profile updated');await load()}catch(e){notify(e.message,'danger')}finally{saving.value=false}}
function fmt(v){return v?new Date(v).toLocaleString(undefined,{year:'numeric',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',hour12:true}):'—'}
function isDateField(key){return key.endsWith('_at')||key.endsWith('_start')||key.endsWith('_end')}
function toLocalInput(date){const local=new Date(date.getTime()-date.getTimezoneOffset()*60000);return local.toISOString().slice(0,16)}
function setSlotNow(key){slotForm.value[key]=toLocalInput(new Date())}
function shiftSlotTime(key,direction){const date=slotForm.value[key]?new Date(slotForm.value[key]):new Date();if(Number.isNaN(date.getTime()))return;date.setMinutes(date.getMinutes()+direction*(Number(slotTimeStep.value)||15));slotForm.value[key]=toLocalInput(date)}
</script>
<template>
 <div class="page-heading"><div><div class="eyebrow">{{examiner?'EXAMINER WORKSPACE':'STUDENT WORKSPACE'}}</div><h1>{{title}}</h1><p class="muted">{{examiner?'Your assigned examination activity and student assessments.':'Discover examinations and manage your academic bookings.'}}</p></div></div>
 <div v-if="error" class="alert alert-danger">{{error}} <button class="btn btn-sm btn-light" @click="load">Retry</button></div>
 <template v-if="['my-examinations','browse-examinations','my-slots','booked-students','evaluations','my-bookings','examination-history','results'].includes(section)">
  <section v-if="section==='my-slots'" class="panel-card slot-create-card"><div class="panel-heading"><div><h3>Create an examination slot</h3><p>Available only during the configured slot-creation window.</p></div></div><form class="slot-create-form" @submit.prevent="createSlot"><select v-model="selectedExam" class="form-select" required><option value="">Choose assigned examination</option><option v-for="x in examinations" :value="x.id">{{x.title}} · {{x.course_code}} ({{x.status}})</option></select><label class="slot-time-field">Start time<input v-model="slotForm.starts_at" type="datetime-local" class="form-control" required><span class="time-quick-controls"><button type="button" class="btn btn-sm btn-light" @click="shiftSlotTime('starts_at',-1)">−</button><input v-model.number="slotTimeStep" type="number" min="1" max="10080" aria-label="Custom time adjustment in minutes"><span>min</span><button type="button" class="btn btn-sm btn-light" @click="shiftSlotTime('starts_at',1)">+</button><button type="button" class="btn btn-sm btn-outline-primary" @click="setSlotNow('starts_at')">Now</button></span></label><label class="slot-time-field">End time<input v-model="slotForm.ends_at" type="datetime-local" class="form-control" required><span class="time-quick-controls"><button type="button" class="btn btn-sm btn-light" @click="shiftSlotTime('ends_at',-1)">−</button><input v-model.number="slotTimeStep" type="number" min="1" max="10080" aria-label="Custom time adjustment in minutes"><span>min</span><button type="button" class="btn btn-sm btn-light" @click="shiftSlotTime('ends_at',1)">+</button><button type="button" class="btn btn-sm btn-outline-primary" @click="setSlotNow('ends_at')">Now</button></span></label><input v-model.number="slotForm.capacity" type="number" min="1" max="100" class="form-control" required placeholder="Capacity"><input v-model="slotForm.meeting_link" class="form-control" placeholder="Meeting link (optional)"><button class="btn btn-primary" :disabled="saving">{{saving?'Creating…':'Create slot'}}</button></form></section>
  <section class="panel-card records-card"><div class="record-toolbar"><div class="search-control"><span>⌕</span><input v-model="search" :placeholder="section==='browse-examinations'?'Search examination or course…':'Search records…'"></div><template v-if="section==='browse-examinations'"><select v-model="courseFilter" class="form-select status-filter"><option value="">All courses</option><option v-for="c in examinations" :value="c.course_id">{{c.course_code}}</option></select><select v-model="typeFilter" class="form-select status-filter"><option value="">All types</option><option v-for="t in ['Viva','Practical','Project Demo','Assessment']" :value="t">{{t}}</option></select></template><select v-if="['my-bookings','evaluations'].includes(section)" v-model="status" class="form-select status-filter"><option value="">All statuses</option><option v-for="s in ['booked','cancelled','completed','pending','draft','submitted','published']" :value="s">{{s}}</option></select><span class="record-count">{{total}} records</span></div><div v-if="loading" class="loading-state">Loading records…</div><div v-else-if="!items.length" class="portal-empty"><strong>No {{title.toLowerCase()}} yet</strong><span>New activity will appear here when it becomes available.</span><RouterLink v-if="section==='browse-examinations'" class="btn btn-primary btn-sm" to="/student/my-bookings">View my bookings</RouterLink></div><div v-else class="table-responsive"><ExaminerSlotsTable v-if="section==='my-slots'" :items="items" @capacity="slotAction($event,'capacity')" @cancel="slotAction($event,'cancel')" /><table v-else class="table admin-table"><thead><tr><th v-for="key in Object.keys(items[0]).filter(k=>!['id','student_id','examiner_id','examination_id','slot_id','booking_id','evaluation_id','criteria'].includes(k))" :key="key">{{key.replaceAll('_',' ')}}</th><th>Actions</th></tr></thead><tbody><tr v-for="x in items" :key="x.id||x.booking_id||x.evaluation_id"><td v-for="key in Object.keys(items[0]).filter(k=>!['id','student_id','examiner_id','examination_id','slot_id','booking_id','evaluation_id','criteria'].includes(k))" :key="key">{{isDateField(key)?fmt(x[key]):x[key]??'—'}}</td><td class="actions-cell"><button v-if="['my-examinations','browse-examinations'].includes(section)" class="btn btn-sm btn-light" @click="inspect(x)">Details</button><button v-if="section==='booked-students'" class="btn btn-sm btn-primary" @click="openEvaluation(x)">Evaluate</button><button v-if="section==='evaluations'&&x.status!=='submitted'&&x.status!=='published'" class="btn btn-sm btn-primary" @click="openEvaluation(x)">Evaluate</button><button v-if="section==='my-bookings'&&['booked','completed'].includes(x.status)&&!['submitted','published'].includes(x.evaluation_status)" class="btn btn-sm btn-outline-primary" @click="submissionBooking=x">Submit work</button><button v-if="section==='my-bookings'&&x.status==='booked'" class="btn btn-sm btn-outline-danger" @click="cancel(x)">Cancel</button><button v-if="section==='results'" class="btn btn-sm btn-primary" @click="showResult(x)">Scorecard</button><button v-if="section==='my-slots'" class="btn btn-sm btn-light" @click="slotAction(x,'capacity')">Capacity</button><button v-if="section==='my-slots'" class="btn btn-sm btn-outline-warning" @click="slotAction(x,'cancel')">Cancel slot</button></td></tr></tbody></table></div><div class="pagination-row"><span>{{items.length}} of {{total}}</span><div><button class="btn btn-sm btn-light" :disabled="page<=1" @click="page--">Previous</button><span>Page {{page}} of {{Math.max(1,pages)}}</span><button class="btn btn-sm btn-light" :disabled="page>=pages" @click="page++">Next</button></div></div></section>
 </template>
 <section v-if="section==='profile'&&profile.user" class="profile-card"><div class="profile-banner"><div class="profile-avatar">{{profile.user.full_name[0]}}</div><div><strong>{{profile.user.full_name}}</strong><span>{{examiner?'Examiner':'Student'}} profile</span></div></div><form class="profile-form" @submit.prevent="saveProfile"><label>Full name<input v-model="profile.user.full_name" required></label><label>Email<input v-model="profile.user.email" type="email" required></label><label>Department<input v-model="profile.department"></label><template v-if="!examiner"><label>Program<input v-model="profile.program"></label><label>Student number<input v-model="profile.student_number"></label></template><template v-if="examiner"><label>Assigned examinations<input :value="profile.workload.examinations" disabled></label><label>Slots<input :value="profile.workload.slots" disabled></label><label>Bookings<input :value="profile.workload.bookings" disabled></label></template><button class="btn btn-primary" :disabled="saving">Save profile</button></form></section>
 <div v-if="detail&&section==='browse-examinations'" class="modal-backdrop-custom" @click.self="detail=null"><section class="form-modal"><div class="modal-head"><div><div class="eyebrow">EXAMINATION DETAILS</div><h2>{{detail.item.title}}</h2><p class="muted">{{detail.item.course_code}} · {{detail.item.type}}</p></div><button @click="detail=null">×</button></div><p>{{detail.item.description||'No additional instructions.'}}</p><p>{{detail.item.duration_minutes}} minutes · {{detail.item.max_marks}} marks</p><div v-if="detail.eligible_to_book" class="slot-choice" v-for="s in detail.slots" :key="s.id"><span>{{fmt(s.starts_at)}} · {{s.examiner}} · {{s.available_seats}} seats</span><button class="btn btn-sm btn-primary" @click="book(s)">Book slot</button></div><p v-if="!detail.slots.length" class="muted">No available slots at this time.</p><p v-if="detail.eligibility_reason" class="alert alert-info">{{detail.eligibility_reason}}</p></section></div>
 <div v-if="detail&&section==='my-examinations'" class="modal-backdrop-custom" @click.self="detail=null"><section class="form-modal"><div class="modal-head"><div><div class="eyebrow">EXAMINATION PLAN</div><h2>{{detail.item.title}}</h2></div><button @click="detail=null">×</button></div><p>{{detail.instructions||'No instructions supplied.'}}</p><h3>Timeline</h3><div v-for="(v,k) in detail.timeline" class="detail-pair"><span>{{k.replaceAll('_',' ')}}</span><strong>{{fmt(v)}}</strong></div><h3>Rubric</h3><div v-for="c in detail.rubric" class="detail-pair"><span>{{c.name}} · {{c.weightage}}%</span><strong>{{c.max_score}} marks</strong></div><h3>Slots and booked students</h3><div v-for="s in detail.slots" class="detail-pair"><span>{{fmt(s.starts_at)}} · {{s.status}}</span><strong>{{s.booked_seats}} / {{s.capacity}}</strong></div><div v-for="b in detail.booked_students" class="detail-pair"><span>{{b.student}} · {{b.booking_status}}</span><strong>{{b.evaluation_status}}</strong></div></section></div>
 <div v-if="detail&&section==='evaluations'" class="modal-backdrop-custom" @click.self="detail=null"><section class="form-modal evaluation-modal"><div class="modal-head"><div><div class="eyebrow">EVALUATION</div><h2>{{detail.student}}</h2><p class="muted">{{detail.examination}} · {{detail.course}}</p></div><button @click="detail=null">×</button></div><div v-if="detail.submission" class="evaluation-submission"><div><strong>Student work attached</strong><span>{{detail.submission.filename}}</span></div><button type="button" class="btn btn-sm btn-outline-primary" @click="downloadWork(detail.submission)">Download {{detail.submission_label}}</button></div><p v-else class="muted">No work document has been submitted for this booking.</p><form @submit.prevent="saveEvaluation(false)"><div v-for="c in scoreRows" :key="c.id" class="score-row"><div><strong>{{c.name}}</strong><small>{{c.description}} · max {{c.max_score}} · {{c.weightage}}%</small></div><input v-model="c.score" type="number" min="0" :max="c.max_score" step="0.01" class="form-control" placeholder="Marks"><textarea v-model="c.feedback" class="form-control" rows="2" placeholder="Remarks for student"></textarea></div><div class="modal-actions"><button type="button" class="btn btn-light" :disabled="saving" @click="saveEvaluation(false)">Save draft</button><button type="button" class="btn btn-primary" :disabled="saving" @click="saveEvaluation(true)">Submit evaluation</button></div></form></section></div>
 <div v-if="result" class="modal-backdrop-custom" @click.self="result=null"><section class="form-modal scorecard"><div class="modal-head"><div><div class="eyebrow">PUBLISHED SCORECARD</div><h2>{{result.examination}}</h2><p>{{result.course}}</p></div><button @click="result=null">×</button></div><div class="score-total">{{result.total_marks}} <small>/ {{result.maximum_marks}}</small><span>Total marks</span></div><div v-for="c in result.criteria" class="detail-pair"><span>{{c.criterion}}<small class="d-block">{{c.feedback}}</small></span><strong>{{c.score}} / {{c.maximum}}</strong></div><p class="muted mt-3">Evaluated {{fmt(result.evaluation_date)}}</p><button class="btn btn-outline-primary mt-2" onclick="window.print()">Print scorecard</button></section></div>
 <WorkSubmissionModal v-if="submissionBooking" :booking="submissionBooking" @close="submissionBooking=null" @saved="load" />
</template>

